def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row if v}
    objs = []
    for c in colors:
        cells = [(r, x) for r in range(h) for x in range(w) if grid[r][x] == c]
        r0, r1 = min(r for r, x in cells), max(r for r, x in cells)
        x0, x1 = min(x for r, x in cells), max(x for r, x in cells)
        shape = [[c if grid[r0+i][x0+j] == c else 0
                  for j in range(x1-x0+1)] for i in range(r1-r0+1)]
        objs.append((r0, x0, shape))
    # Arrange the extracted motifs along the axis on which their centers vary most.
    rc = [o[0] + (len(o[2])-1)/2 for o in objs]
    xc = [o[1] + (len(o[2][0])-1)/2 for o in objs]
    horizontal = max(xc)-min(xc) >= max(rc)-min(rc)
    objs.sort(key=lambda o: o[1] if horizontal else o[0])
    if horizontal:
        height = max(len(s) for _, _, s in objs)
        width = sum(len(s[0]) for _, _, s in objs)
        out = [[0]*width for _ in range(height)]
        xoff = 0
        for _, _, s in objs:
            for i, row in enumerate(s):
                for j, v in enumerate(row):
                    out[i][xoff+j] = v
            xoff += len(s[0])
    else:
        width = max(len(s[0]) for _, _, s in objs)
        height = sum(len(s) for _, _, s in objs)
        out = [[0]*width for _ in range(height)]
        yoff = 0
        for _, _, s in objs:
            for i, row in enumerate(s):
                for j, v in enumerate(row):
                    out[yoff+i][j] = v
            yoff += len(s)
    return out
